{
  "findings": [
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 Bucket Public Access Block is disabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "HIGH",
      "explanation": "The 'restrict_public_buckets' attribute is explicitly set to false, which allows public access policies on the S3 bucket. This misconfiguration can lead to unintended data exposure if a public bucket policy or ACL is applied."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n  restrict_public_buckets = true\n}",
  "fix_summary": "Changed 'restrict_public_buckets' from false to true in the aws_s3_bucket_public_access_block resource to enforce that the S3 bucket does not allow public access via bucket policies or ACLs."
}
